/**
 * A re-implementation of CPython's `json.loads` sufficient for this tool.
 *
 * Differences from `JSON.parse` that actually matter here:
 *   - `NaN` / `Infinity` / `-Infinity` are accepted (Python allows them).
 *   - Integer and float literals stay distinguishable (see `./numbers.mjs`).
 *   - Integers wider than 2**53 keep full precision as `bigint`.
 *   - Error messages follow `json.decoder.JSONDecodeError`'s wording so the
 *     failure path looks like the original program's.
 */

import { pyFloat } from './numbers.mjs';

export class JSONDecodeError extends Error {
  constructor(msg, doc, pos) {
    const lineno = doc.slice(0, pos).split('\n').length;
    const colno = pos - doc.lastIndexOf('\n', pos - 1);
    super(`${msg}: line ${lineno} column ${colno} (char ${pos})`);
    this.name = 'JSONDecodeError';
    this.pythonType = 'json.decoder.JSONDecodeError';
    this.doc = doc;
    this.pos = pos;
    this.lineno = lineno;
    this.colno = colno;
  }
}

const WHITESPACE = new Set([' ', '\t', '\n', '\r']);

const STRING_ESCAPES = {
  '"': '"',
  '\\': '\\',
  '/': '/',
  b: '\b',
  f: '\f',
  n: '\n',
  r: '\r',
  t: '\t',
};

const NUMBER_RE =
  /^(-?(?:0|[1-9]\d*))(\.\d+)?([eE][-+]?\d+)?/;

class Decoder {
  constructor(text) {
    this.doc = text;
    this.pos = 0;
  }

  error(msg, pos = this.pos) {
    throw new JSONDecodeError(msg, this.doc, pos);
  }

  skipWhitespace() {
    while (this.pos < this.doc.length && WHITESPACE.has(this.doc[this.pos])) {
      this.pos += 1;
    }
  }

  decode() {
    this.skipWhitespace();
    if (this.pos >= this.doc.length) {
      this.error('Expecting value');
    }
    const value = this.parseValue();
    this.skipWhitespace();
    if (this.pos < this.doc.length) {
      this.error('Extra data');
    }
    return value;
  }

  parseValue() {
    const doc = this.doc;
    const ch = doc[this.pos];

    if (ch === '"') return this.parseString();
    if (ch === '{') return this.parseObject();
    if (ch === '[') return this.parseArray();

    if (doc.startsWith('true', this.pos)) {
      this.pos += 4;
      return true;
    }
    if (doc.startsWith('false', this.pos)) {
      this.pos += 5;
      return false;
    }
    if (doc.startsWith('null', this.pos)) {
      this.pos += 4;
      return null;
    }
    if (doc.startsWith('NaN', this.pos)) {
      this.pos += 3;
      return pyFloat(NaN);
    }
    if (doc.startsWith('Infinity', this.pos)) {
      this.pos += 8;
      return pyFloat(Infinity);
    }
    if (doc.startsWith('-Infinity', this.pos)) {
      this.pos += 9;
      return pyFloat(-Infinity);
    }

    const match = NUMBER_RE.exec(doc.slice(this.pos));
    if (match) {
      this.pos += match[0].length;
      return makeNumber(match[1], match[2], match[3]);
    }

    this.error('Expecting value');
    return undefined;
  }

  parseString() {
    const doc = this.doc;
    const begin = this.pos;
    this.pos += 1; // opening quote
    let out = '';
    let chunkStart = this.pos;

    for (;;) {
      if (this.pos >= doc.length) {
        this.error('Unterminated string starting at', begin);
      }
      const ch = doc[this.pos];

      if (ch === '"') {
        out += doc.slice(chunkStart, this.pos);
        this.pos += 1;
        return out;
      }

      if (ch === '\\') {
        out += doc.slice(chunkStart, this.pos);
        this.pos += 1;
        if (this.pos >= doc.length) {
          this.error('Unterminated string starting at', begin);
        }
        const esc = doc[this.pos];
        if (esc === 'u') {
          out += this.parseUnicodeEscape();
        } else if (Object.prototype.hasOwnProperty.call(STRING_ESCAPES, esc)) {
          out += STRING_ESCAPES[esc];
          this.pos += 1;
        } else {
          this.error(`Invalid \\escape: ${JSON.stringify(esc)}`, this.pos - 1);
        }
        chunkStart = this.pos;
        continue;
      }

      // `json.loads` is strict by default: raw control characters are illegal.
      if (ch < ' ') {
        this.error(
          `Invalid control character ${controlRepr(ch)} at`,
          this.pos,
        );
      }
      this.pos += 1;
    }
  }

  parseUnicodeEscape() {
    // `this.pos` sits on the "u".
    const hex = this.doc.slice(this.pos + 1, this.pos + 5);
    if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
      this.error('Invalid \\uXXXX escape', this.pos + 1);
    }
    let code = parseInt(hex, 16);
    this.pos += 5;

    // Python's decoder joins surrogate pairs into a single code point.
    if (code >= 0xd800 && code <= 0xdbff && this.doc.startsWith('\\u', this.pos)) {
      const lowHex = this.doc.slice(this.pos + 2, this.pos + 6);
      if (/^[0-9a-fA-F]{4}$/.test(lowHex)) {
        const low = parseInt(lowHex, 16);
        if (low >= 0xdc00 && low <= 0xdfff) {
          this.pos += 6;
          code = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
        }
      }
    }
    return String.fromCodePoint(code);
  }

  parseObject() {
    const result = Object.create(null);
    this.pos += 1; // '{'
    this.skipWhitespace();

    if (this.doc[this.pos] === '}') {
      this.pos += 1;
      return toPlainObject(result);
    }

    for (;;) {
      this.skipWhitespace();
      if (this.doc[this.pos] !== '"') {
        this.error('Expecting property name enclosed in double quotes');
      }
      const key = this.parseString();
      this.skipWhitespace();
      if (this.doc[this.pos] !== ':') {
        this.error("Expecting ':' delimiter");
      }
      this.pos += 1;
      this.skipWhitespace();
      if (this.pos >= this.doc.length) {
        this.error('Expecting value');
      }
      // Later duplicates win, exactly as in CPython.
      delete result[key];
      result[key] = this.parseValue();
      this.skipWhitespace();
      const ch = this.doc[this.pos];
      if (ch === '}') {
        this.pos += 1;
        return toPlainObject(result);
      }
      if (ch !== ',') {
        this.error("Expecting ',' delimiter");
      }
      this.pos += 1;
    }
  }

  parseArray() {
    const result = [];
    this.pos += 1; // '['
    this.skipWhitespace();

    if (this.doc[this.pos] === ']') {
      this.pos += 1;
      return result;
    }

    for (;;) {
      this.skipWhitespace();
      if (this.pos >= this.doc.length) {
        this.error('Expecting value');
      }
      result.push(this.parseValue());
      this.skipWhitespace();
      const ch = this.doc[this.pos];
      if (ch === ']') {
        this.pos += 1;
        return result;
      }
      if (ch !== ',') {
        this.error("Expecting ',' delimiter");
      }
      this.pos += 1;
    }
  }
}

function controlRepr(ch) {
  const code = ch.charCodeAt(0);
  const named = { 9: "'\\t'", 10: "'\\n'", 13: "'\\r'" };
  if (named[code]) return named[code];
  return `'\\x${code.toString(16).padStart(2, '0')}'`;
}

function makeNumber(integer, frac, exp) {
  if (frac || exp) {
    return pyFloat(Number(integer + (frac || '') + (exp || '')));
  }
  const asNumber = Number(integer);
  if (Number.isSafeInteger(asNumber)) return asNumber;
  return BigInt(integer);
}

/**
 * Objects are built null-prototyped so that keys such as "__proto__" or
 * "constructor" behave like ordinary Python dict keys, then handed back with a
 * null prototype intact — every read in this library uses explicit helpers.
 */
function toPlainObject(obj) {
  return obj;
}

export function loads(text) {
  if (typeof text !== 'string') {
    throw new TypeError('the JSON object must be str, bytes or bytearray');
  }
  return new Decoder(text).decode();
}

