/**
 * Equality as `jsonschema._utils.equal` defines it.
 *
 * The subtlety it exists to handle: in Python `bool` subclasses `int`, so a
 * naive `True == 1` is true — which JSON Schema says it must not be.  The
 * library sidesteps that by mapping booleans onto private sentinels before
 * comparing, and recursing into lists and dicts to do the same.  Numbers of
 * different Python types still compare equal, so `1 == 1.0` holds.
 */

import { isPyNumber, numbersEqual } from './numbers.mjs';
import { isArray, isObject, keysOf, hasKey } from './values.mjs';

export function equal(one, two) {
  if (typeof one === 'string' || typeof two === 'string') {
    return one === two;
  }
  if (isArray(one) && isArray(two)) {
    return sequenceEqual(one, two);
  }
  if (isObject(one) && isObject(two)) {
    return mappingEqual(one, two);
  }
  // `unbool` territory: booleans only ever equal the identical boolean.
  if (one === true || one === false || two === true || two === false) {
    return one === two;
  }
  if (isPyNumber(one) && isPyNumber(two)) {
    return numbersEqual(one, two);
  }
  if (one === null || two === null) {
    return one === two;
  }
  return one === two;
}

function sequenceEqual(one, two) {
  if (one.length !== two.length) return false;
  for (let i = 0; i < one.length; i += 1) {
    if (!equal(one[i], two[i])) return false;
  }
  return true;
}

function mappingEqual(one, two) {
  const oneKeys = keysOf(one);
  if (oneKeys.length !== keysOf(two).length) return false;
  for (const key of oneKeys) {
    if (!hasKey(two, key)) return false;
    if (!equal(one[key], two[key])) return false;
  }
  return true;
}

/**
 * `jsonschema._utils.uniq` — true when no two elements compare equal.
 *
 * CPython first tries a sort-then-scan fast path and falls back to an O(n^2)
 * membership scan whenever the elements are not mutually orderable.  Both
 * paths agree on the answer, so a single quadratic scan reproduces it.
 */
export function uniq(container) {
  const seen = [];
  for (const element of container) {
    for (const previous of seen) {
      if (equal(previous, element)) return false;
    }
    seen.push(element);
  }
  return true;
}

