/**
 * A focused re-implementation of the pieces of Python's `argparse` that the
 * original script exercises: two required, string-valued long options plus the
 * automatic `-h/--help`.  Usage text, error wording and exit codes follow
 * `argparse.ArgumentParser` so the CLI surface is indistinguishable.
 */

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.optionals = [
      {
        flags: ['-h', '--help'],
        dest: 'help',
        action: 'help',
        help: 'show this help message and exit',
      },
    ];
  }

  addArgument(flag, { dest, required = false, help = '' } = {}) {
    this.optionals.push({
      flags: [flag],
      dest: dest || flag.replace(/^--?/, '').replace(/-/g, '_'),
      metavar: (dest || flag.replace(/^--?/, '')).toUpperCase(),
      action: 'store',
      required,
      help,
    });
    return this;
  }

  formatUsage() {
    const parts = this.optionals.map((option) => {
      if (option.action === 'help') return '[-h]';
      const body = `${option.flags[0]} ${option.metavar}`;
      return option.required ? body : `[${body}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const rows = this.optionals.map((option) => {
      const invocation =
        option.action === 'help'
          ? option.flags.join(', ')
          : `${option.flags[0]} ${option.metavar}`;
      return [invocation, option.help];
    });

    // argparse aligns help text in a column two spaces past the widest
    // invocation, capped so long invocations wrap instead of pushing it out.
    const width = Math.max(...rows.map((row) => row[0].length));
    const body = rows
      .map(([invocation, help]) => `  ${invocation.padEnd(width)}  ${help}`)
      .join('\n');

    return `${this.formatUsage()}\noptions:\n${body}\n`;
  }

  error(message) {
    const err = new ArgumentError(`${this.prog}: error: ${message}\n`);
    err.usage = this.formatUsage();
    throw err;
  }

  /** Resolve `--abc` against the declared long options, allowing prefixes. */
  matchOption(name) {
    const exact = this.optionals.find((option) => option.flags.includes(name));
    if (exact) return exact;

    if (name.startsWith('--')) {
      const candidates = this.optionals.filter((option) =>
        option.flags.some((flag) => flag.startsWith(name)),
      );
      const dests = new Set(candidates.map((option) => option.dest));
      if (dests.size === 1) return candidates[0];
      if (dests.size > 1) {
        const listed = candidates
          .flatMap((option) => option.flags)
          .filter((flag) => flag.startsWith(name))
          .join(', ');
        this.error(`ambiguous option: ${name} could match ${listed}`);
      }
    }
    return null;
  }

  parseArgs(argv) {
    const namespace = Object.create(null);
    for (const option of this.optionals) {
      if (option.action === 'store') namespace[option.dest] = null;
    }

    const extras = [];
    let i = 0;
    let onlyPositionals = false;

    while (i < argv.length) {
      const arg = argv[i];

      if (onlyPositionals) {
        extras.push(arg);
        i += 1;
        continue;
      }

      if (arg === '--') {
        onlyPositionals = true;
        i += 1;
        continue;
      }

      if (!looksLikeOption(arg)) {
        extras.push(arg);
        i += 1;
        continue;
      }

      const eq = arg.indexOf('=');
      const name = eq === -1 ? arg : arg.slice(0, eq);
      const inlineValue = eq === -1 ? null : arg.slice(eq + 1);
      const option = this.matchOption(name);

      if (!option) {
        extras.push(arg);
        i += 1;
        continue;
      }

      if (option.action === 'help') {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      if (inlineValue !== null) {
        namespace[option.dest] = inlineValue;
        i += 1;
        continue;
      }

      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        this.error(`argument ${option.flags.join('/')}: expected one argument`);
      }
      namespace[option.dest] = next;
      i += 2;
    }

    const missing = this.optionals
      .filter((option) => option.required && namespace[option.dest] === null)
      .map((option) => option.flags.join('/'));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length) {
