/**
 * Translation of Python `re` patterns into JavaScript `RegExp` objects.
 *
 * `jsonschema` applies `pattern` and `patternProperties` with `re.search`, so
 * the differences that matter are the ones between the two regex dialects:
 *
 *   - Python's `\d`, `\w` and `\s` are Unicode-aware; JavaScript's are ASCII.
 *   - Python's `$` also matches just before a single trailing newline.
 *   - Python spells named groups `(?P<name>...)` and backreferences `(?P=n)`.
 *   - Python accepts `{,n}` and inline flag groups such as `(?i)`.
 */

/** Code points for which Python's `str.isspace()` is true. */
const PY_SPACE =
  '\\t\\n\\v\\f\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000';

const JS_SYNTAX_CHARS = new Set(['^', '$', '\\', '.', '*', '+', '?', '(', ')', '[', ']', '{', '}', '|', '/']);

const INLINE_FLAGS = /\(\?([aiLmsux]+)\)/g;

class PatternSyntaxError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PatternSyntaxError';
    this.pythonType = 're.error';
  }
}

export { PatternSyntaxError };

/** Expand a Python class escape. `inClass` selects a bracketable spelling. */
function classEscape(letter, inClass, ascii) {
  if (ascii) {
    return inClass ? `\\${letter}` : `\\${letter}`;
  }
  switch (letter) {
    case 'd':
      return inClass ? '\\p{Nd}' : '[\\p{Nd}]';
    case 'D':
      return '\\P{Nd}';
    case 'w':
      return inClass ? '\\p{L}\\p{N}_' : '[\\p{L}\\p{N}_]';
    case 'W':
      // A negated union has no in-class spelling without the `v` flag; the
      // ASCII form is the closest available approximation there.
      return inClass ? '\\W' : '[^\\p{L}\\p{N}_]';
    case 's':
      return inClass ? PY_SPACE : `[${PY_SPACE}]`;
    case 'S':
      return inClass ? '\\S' : `[^${PY_SPACE}]`;
    default:
      return `\\${letter}`;
  }
}

/** Strip `(?x)`-style verbose whitespace and `#` comments. */
function stripVerbose(pattern) {
  let out = '';
  let inClass = false;
  for (let i = 0; i < pattern.length; i += 1) {
    const ch = pattern[i];
    if (ch === '\\') {
      out += ch + (pattern[i + 1] ?? '');
      i += 1;
      continue;
    }
    if (inClass) {
      if (ch === ']') inClass = false;
      out += ch;
      continue;
    }
    if (ch === '[') {
      inClass = true;
      out += ch;
      continue;
    }
    if (ch === '#') {
      while (i < pattern.length && pattern[i] !== '\n') i += 1;
      continue;
    }
    if (/\s/.test(ch)) continue;
    out += ch;
  }
  return out;
}

function translate(pattern, { ascii }) {
  let out = '';
  let inClass = false;
  let i = 0;

  while (i < pattern.length) {
    const ch = pattern[i];

    if (ch === '\\') {
      const next = pattern[i + 1];
      i += 2;
      if (next === undefined) {
        throw new PatternSyntaxError('bad escape (end of pattern)');
      }
      if ('dDwWsS'.includes(next)) {
        out += classEscape(next, inClass, ascii);
      } else if (next === 'A' && !inClass) {
        out += '^';
      } else if (next === 'Z' && !inClass) {
        out += '$';
      } else if (/[a-zA-Z0-9]/.test(next)) {
        out += `\\${next}`;
      } else if (JS_SYNTAX_CHARS.has(next) || (inClass && next === '-')) {
        out += `\\${next}`;
      } else {
        // Python permits escaping any punctuation; JavaScript's `u` mode does
        // not, so emit the literal character instead.
        out += next.replace(/[\\^$.*+?()[\]{}|/-]/g, '\\$&');
      }
      continue;
    }

    if (inClass) {
      if (ch === ']') inClass = false;
      out += ch;
      i += 1;
      continue;
    }

    if (ch === '[') {
      inClass = true;
      out += '[';
      i += 1;
      if (pattern[i] === '^') {
        out += '^';
        i += 1;
      }
      // A `]` in first position is a literal in both dialects, but only Python
      // accepts it unescaped.
      if (pattern[i] === ']') {
        out += '\\]';
        i += 1;
      }
      continue;
    }

    if (ch === '$') {
      out += '(?=\\n?$)';
      i += 1;
      continue;
    }

    if (ch === '(' && pattern[i + 1] === '?') {
      const rest = pattern.slice(i);
      let match = /^\(\?P<([^>]+)>/.exec(rest);
      if (match) {
        out += `(?<${match[1]}>`;
        i += match[0].length;
        continue;
      }
      match = /^\(\?P=([^)]+)\)/.exec(rest);
      if (match) {
        out += `\\k<${match[1]}>`;
        i += match[0].length;
        continue;
      }
      if (rest.startsWith('(?#')) {
        const end = pattern.indexOf(')', i);
        if (end === -1) throw new PatternSyntaxError('missing ), unterminated comment');
        i = end + 1;
        continue;
