/**
 * Translation of Python `re` patterns into JavaScript `RegExp` objects.
 *
 * `jsonschema` applies `pattern` and `patternProperties` with `re.search`, so
 * the differences that matter are the ones between the two regex dialects:
 *
 *   - Python's `\d`, `\w` and `\s` are Unicode-aware; JavaScript's are ASCII.
 *   - Python's `$` also matches just before a single trailing newline.
 *   - Python spells named groups `(?P<name>...)` and backreferences `(?P=n)`.
 *   - Python accepts `{,n}` and inline flag groups such as `(?i)`.
 */

/** Code points for which Python's `str.isspace()` is true. */
const PY_SPACE =
  '\\t\\n\\v\\f\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000';

const JS_SYNTAX_CHARS = new Set(['^', '$', '\\', '.', '*', '+', '?', '(', ')', '[', ']', '{', '}', '|', '/']);

const INLINE_FLAGS = /\(\?([aiLmsux]+)\)/g;

class PatternSyntaxError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PatternSyntaxError';
    this.pythonType = 're.error';
  }
}

export { PatternSyntaxError };

/** Expand a Python class escape. `inClass` selects a bracketable spelling. */
function classEscape(letter, inClass, ascii) {
  if (ascii) {
    return inClass ? `\\${letter}` : `\\${letter}`;
  }
  switch (letter) {
    case 'd':
      return inClass ? '\\p{Nd}' : '[\\p{Nd}]';
    case 'D':
      return '\\P{Nd}';
    case 'w':
      return inClass ? '\\p{L}\\p{N}_' : '[\\p{L}\\p{N}_]';
    case 'W':
      // A negated union has no in-class spelling without the `v` flag; the
      // ASCII form is the closest available approximation there.
      return inClass ? '\\W' : '[^\\p{L}\\p{N}_]';
    case 's':
      return inClass ? PY_SPACE : `[${PY_SPACE}]`;
    case 'S':
      return inClass ? '\\S' : `[^${PY_SPACE}]`;
    default:
      return `\\${letter}`;
  }
}

/** Strip `(?x)`-style verbose whitespace and `#` comments. */
function stripVerbose(pattern) {
  let out = '';
