/** Exception types mirroring the ones `jsonschema` raises or collects. */

export class ValidationError {
  constructor(message, { context = [], path = [], schemaPath = [], validator = null } = {}) {
    this.message = message;
    this.context = context;
    this.path = path;
    this.schemaPath = schemaPath;
    this.validator = validator;
  }
}

export class SchemaError extends Error {
  constructor(message) {
    super(message);
    this.name = 'SchemaError';
    this.pythonType = 'jsonschema.exceptions.SchemaError';
  }
}

export class UnknownType extends Error {
  constructor(type) {
    super(`Unknown type ${JSON.stringify(type)}`);
    this.name = 'UnknownType';
    this.pythonType = 'jsonschema.exceptions.UnknownType';
    this.type = type;
  }
}

export class Unresolvable extends Error {
  constructor(ref) {
    super(String(ref));
    this.name = 'Unresolvable';
    this.pythonType = 'referencing.exceptions.Unresolvable';
    this.ref = ref;
  }
}

/**
 * Raised where CPython would raise `TypeError` / `AttributeError` from inside
 * the library — for instance when a schema is a number rather than an object.
 */
export class PythonTypeError extends Error {
  constructor(message, pythonType = 'TypeError') {
    super(message);
    this.name = pythonType;
    this.pythonType = pythonType;
  }
}

