/**
 * Per-draft type checkers, matching `jsonschema._types`.
 *
 * Two details drive the whole design:
 *   - `bool` is a subclass of `int` in Python, so booleans are explicitly
 *     rejected by the "integer" and "number" checks.
 *   - Draft 3 and Draft 4 call `1.0` a float, not an integer; Draft 6 onwards
 *     redefine "integer" to accept any float with a zero fractional part.
 */

import { PyFloat, isPyNumber, isIntegral } from './json/numbers.mjs';
import { isArray, isObject, isString, isBool, isNull } from './json/values.mjs';
import { UnknownType } from './errors.mjs';

const isAny = () => true;
const isArrayType = (instance) => isArray(instance);
const isBoolType = (instance) => isBool(instance);
const isObjectType = (instance) => isObject(instance);
const isNullType = (instance) => isNull(instance);
const isStringType = (instance) => isString(instance);
const isNumberType = (instance) => !isBool(instance) && isPyNumber(instance);

/** Python `isinstance(x, int) and not isinstance(x, bool)`. */
const isStrictInteger = (instance) =>
  !isBool(instance) && (typeof instance === 'number' || typeof instance === 'bigint');

/** Draft 6+ also accepts floats whose value is integral. */
const isIntegerOrIntegralFloat = (instance) =>
  isStrictInteger(instance) ||
  (instance instanceof PyFloat && isIntegral(instance));

const DRAFT3_CHECKS = {
  any: isAny,
  array: isArrayType,
  boolean: isBoolType,
  integer: isStrictInteger,
  object: isObjectType,
  null: isNullType,
  number: isNumberType,
  string: isStringType,
};

const DRAFT4_CHECKS = { ...DRAFT3_CHECKS };
delete DRAFT4_CHECKS.any;

const DRAFT6_CHECKS = { ...DRAFT4_CHECKS, integer: isIntegerOrIntegralFloat };

export class TypeChecker {
  constructor(checks) {
    this.checks = checks;
  }

  isType(instance, type) {
    const check = Object.prototype.hasOwnProperty.call(this.checks, type)
      ? this.checks[type]
      : undefined;
    if (check === undefined) throw new UnknownType(type);
    return check(instance);
  }
}

export const draft3TypeChecker = new TypeChecker(DRAFT3_CHECKS);
export const draft4TypeChecker = new TypeChecker(DRAFT4_CHECKS);
export const draft6TypeChecker = new TypeChecker(DRAFT6_CHECKS);
export const draft7TypeChecker = draft6TypeChecker;
export const draft201909TypeChecker = draft6TypeChecker;
export const draft202012TypeChecker = draft6TypeChecker;

