/**
 * URI handling for `$ref` resolution: RFC 3986 reference resolution plus the
 * fragment splitting that `urllib.parse.urldefrag` performs.
 */

const URI_RE = /^(?:([A-Za-z][A-Za-z0-9+.-]*):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/;

export function parseUri(uri) {
  const match = URI_RE.exec(uri) || [];
  return {
    scheme: match[1] ?? null,
    authority: match[2] ?? null,
    path: match[3] ?? '',
    query: match[4] ?? null,
    fragment: match[5] ?? null,
  };
}

function composeUri({ scheme, authority, path, query, fragment }) {
  let out = '';
  if (scheme !== null && scheme !== undefined) out += `${scheme}:`;
  if (authority !== null && authority !== undefined) out += `//${authority}`;
  out += path;
  if (query !== null && query !== undefined) out += `?${query}`;
  if (fragment !== null && fragment !== undefined) out += `#${fragment}`;
  return out;
}

/** RFC 3986 §5.2.4 */
function removeDotSegments(path) {
  const output = [];
  let input = path;
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3);
    else if (input.startsWith('./')) input = input.slice(2);
    else if (input.startsWith('/./')) input = `/${input.slice(3)}`;
    else if (input === '/.') input = '/';
    else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`;
      output.pop();
    } else if (input === '/..') {
      input = '/';
      output.pop();
    } else if (input === '.' || input === '..') input = '';
    else {
      const start = input[0] === '/' ? 1 : 0;
      const next = input.indexOf('/', start);
      const segment = next === -1 ? input : input.slice(0, next);
      output.push(segment);
      input = next === -1 ? '' : input.slice(next);
    }
  }
  return output.join('');
}

/** RFC 3986 §5.3 reference resolution, equivalent to `urljoin`. */
export function urlJoin(base, ref) {
  if (!base) return ref;
  if (!ref) return base;

  const b = parseUri(base);
  const r = parseUri(ref);
  const target = {};

  if (r.scheme !== null) {
    target.scheme = r.scheme;
    target.authority = r.authority;
    target.path = removeDotSegments(r.path);
    target.query = r.query;
  } else {
    if (r.authority !== null) {
      target.authority = r.authority;
      target.path = removeDotSegments(r.path);
      target.query = r.query;
    } else if (r.path === '') {
      target.path = b.path;
      target.query = r.query !== null ? r.query : b.query;
      target.authority = b.authority;
    } else {
      if (r.path.startsWith('/')) {
        target.path = removeDotSegments(r.path);
      } else {
        target.path = removeDotSegments(mergePaths(b, r.path));
      }
      target.query = r.query;
      target.authority = b.authority;
    }
    target.scheme = b.scheme;
  }

  target.fragment = r.fragment;
  return composeUri(target);
}

function mergePaths(base, relPath) {
  if (base.authority !== null && base.path === '') return `/${relPath}`;
  const cut = base.path.lastIndexOf('/');
  return cut === -1 ? relPath : base.path.slice(0, cut + 1) + relPath;
}

/** `urldefrag`: split off the fragment, returning `[uri, fragment]`. */
export function urlDefrag(uri) {
  const hash = uri.indexOf('#');
  if (hash === -1) return [uri, ''];
  return [uri.slice(0, hash), uri.slice(hash + 1)];
}

/** Percent-decoding as `urllib.parse.unquote` performs it on fragments. */
export function unquote(text) {
  if (!text.includes('%')) return text;
  try {
    return decodeURIComponent(text);
  } catch {
    return text.replace(/%([0-9a-fA-F]{2})/g, (whole, hex) => {
      const code = parseInt(hex, 16);
      return code < 0x80 ? String.fromCharCode(code) : whole;
    });
  }
}

