/** RFC 6901 JSON pointers, as `referencing` resolves them. */

import { isArray, isObject, hasKey } from '../json/values.mjs';
import { Unresolvable } from '../errors.mjs';

export function unescapeToken(token) {
  return token.replace(/~1/g, '/').replace(/~0/g, '~');
}

export function escapeToken(token) {
  return token.replace(/~/g, '~0').replace(/\//g, '~1');
}

export function splitPointer(pointer) {
  if (pointer === '') return [];
  if (!pointer.startsWith('/')) {
    throw new Unresolvable(pointer);
  }
  return pointer.slice(1).split('/').map(unescapeToken);
}

/**
 * Walk `document` along `pointer`.  `onStep` observes each intermediate
 * document so callers can track `$id` base changes along the way.
 */
export function resolvePointer(document, pointer, onStep) {
  let current = document;
  for (const token of splitPointer(pointer)) {
    if (isArray(current)) {
      if (!/^(0|[1-9][0-9]*)$/.test(token)) throw new Unresolvable(pointer);
      const index = Number(token);
      if (index >= current.length) throw new Unresolvable(pointer);
      current = current[index];
    } else if (isObject(current)) {
      if (!hasKey(current, token)) throw new Unresolvable(pointer);
      current = current[token];
    } else {
      throw new Unresolvable(pointer);
    }
    if (onStep) onStep(current);
  }
  return current;
}

