/** Keys whose value is itself a schema. */
const SUBRESOURCE_SCHEMA = {
  draft3: ['additionalItems', 'additionalProperties', 'extends', 'not'],
  draft4: ['additionalItems', 'additionalProperties', 'not'],
  draft6: ['additionalItems', 'additionalProperties', 'contains', 'not', 'propertyNames'],
  draft7: [
    'additionalItems',
    'additionalProperties',
    'contains',
    'else',
    'if',
    'not',
    'propertyNames',
    'then',
  ],
  draft201909: [
    'additionalItems',
    'additionalProperties',
    'contains',
    'contentSchema',
    'else',
    'if',
    'items',
    'not',
    'propertyNames',
    'then',
    'unevaluatedItems',
    'unevaluatedProperties',
  ],
  draft202012: [
    'additionalProperties',
    'contains',
    'contentSchema',
    'else',
    'if',
    'items',
    'not',
    'propertyNames',
    'then',
    'unevaluatedItems',
    'unevaluatedProperties',
  ],
};

/** Keys whose value is an array of schemas. */
const SUBRESOURCE_ARRAY = {
  draft3: ['extends', 'items', 'type'],
  draft4: ['allOf', 'anyOf', 'items', 'oneOf'],
  draft6: ['allOf', 'anyOf', 'items', 'oneOf'],
  draft7: ['allOf', 'anyOf', 'items', 'oneOf'],
  draft201909: ['allOf', 'anyOf', 'items', 'oneOf'],
  draft202012: ['allOf', 'anyOf', 'oneOf', 'prefixItems'],
};

