const SUBRESOURCE_VALUES = {
  draft3: ['definitions', 'patternProperties', 'properties'],
  draft4: ['definitions', 'patternProperties', 'properties'],
  draft6: ['definitions', 'patternProperties', 'properties'],
  draft7: ['definitions', 'patternProperties', 'properties'],
  draft201909: ['$defs', 'definitions', 'dependentSchemas', 'patternProperties', 'properties'],
  draft202012: ['$defs', 'definitions', 'dependentSchemas', 'patternProperties', 'properties'],
};

