/**
 * The schema registry and `$ref` resolver, modelled on the `referencing`
 * package that modern `jsonschema` delegates to.
 *
 * A registry maps absolute URIs to schema resources and plain-name anchors to
 * the subschemas that declare them.  Resources are discovered by crawling the
 * root schema for `$id`/`id` and `$anchor`/`$dynamicAnchor` declarations, and
 * the bundled meta-schema documents are pre-registered so that references to
 * the canonical dialect URIs resolve without network access.
 */

import { isObject, getKey } from '../json/values.mjs';
import { Unresolvable } from '../errors.mjs';
import { urlJoin, urlDefrag, unquote } from './uri.mjs';
import { resolvePointer } from './pointer.mjs';
import { METASCHEMAS } from './metaschemas.mjs';

const anchorKey = (uri, name) => `${uri}�${name}`;

export class Registry {
  constructor() {
    this.resources = new Map();
    this.anchors = new Map();
  }

  addResource(uri, contents, spec) {
    if (!this.resources.has(uri)) {
      this.resources.set(uri, { contents, spec });
    }
  }

  addAnchor(uri, name, contents, dynamic) {
    const key = anchorKey(uri, name);
    if (!this.anchors.has(key)) {
      this.anchors.set(key, { contents, dynamic });
    }
  }

  /**
   * Walk `contents`, registering every embedded resource and anchor found.
   * `baseUri` is the base in effect for `contents` itself.
   */
  crawl(contents, baseUri, spec) {
    const stack = [[contents, baseUri]];
    const visited = new Set();

    while (stack.length) {
      const [current, base] = stack.pop();
      if (isObject(current) && visited.has(current)) continue;
      if (isObject(current)) visited.add(current);

      let uri = base;
      const id = spec.idOf(current);
      if (id !== null) {
        uri = urlDefrag(urlJoin(base, id))[0];
        this.addResource(uri, current, spec);
      }

      for (const anchor of spec.anchorsIn(current)) {
        this.addAnchor(uri, anchor.name, anchor.contents, anchor.dynamic);
      }

      for (const child of spec.subresources(current)) {
        stack.push([child, uri]);
      }
    }
  }
}

/** The registry holding the meta-schema documents shipped with the library. */
export function baseRegistry(specFor) {
  const registry = new Registry();
  for (const [uri, contents] of Object.entries(METASCHEMAS)) {
    const bare = urlDefrag(uri)[0];
    const spec = specFor(contents);
    registry.addResource(bare, contents, spec);
    registry.addResource(uri, contents, spec);
    registry.crawl(contents, bare, spec);
  }
  return registry;
}

export class Resolver {
  constructor(registry, baseUri, previous = null) {
    this.registry = registry;
    this.baseUri = baseUri;
    this.previous = previous;
  }

  /** Base URIs currently on the dynamic scope stack, innermost first. */
  *dynamicScope() {
    let resolver = this;
    while (resolver !== null) {
      yield resolver.baseUri;
      resolver = resolver.previous;
    }
  }

  /** Enter a subschema, adopting its `$id` as the new base if it has one. */
  inSubresource(contents, spec) {
    const id = spec.idOf(contents);
    if (id === null) return this;
    return new Resolver(this.registry, urlJoin(this.baseUri, id), this.previous);
  }

  lookupResource(uri) {
    const found = this.registry.resources.get(uri);
    if (found) return found;
    const withHash = this.registry.resources.get(`${uri}#`);
    if (withHash) return withHash;
    return null;
  }

  /**
   * Resolve `ref` relative to the current base, returning the referenced
   * schema plus a resolver scoped to it.
   */
  lookup(ref) {
    let uri;
    let fragment;
    if (ref.startsWith('#')) {
      uri = urlDefrag(this.baseUri)[0];
      fragment = ref.slice(1);
    } else {
      [uri, fragment] = urlDefrag(urlJoin(this.baseUri, ref));
    }

    const resource = this.lookupResource(uri);
    if (resource === null) throw new Unresolvable(ref);

    const { spec } = resource;
    let base = uri;

    if (fragment.startsWith('/')) {
      // Track `$id` declarations passed on the way down: they move the base.
      const contents = resolvePointer(resource.contents, unquote(fragment), (step) => {
        const id = spec.idOf(step);
        if (id !== null) base = urlDefrag(urlJoin(base, id))[0];
      });
      return {
        contents,
        resolver: new Resolver(this.registry, base, this),
      };
    }

    if (fragment) {
      const anchor = this.registry.anchors.get(anchorKey(uri, unquote(fragment)));
      if (anchor === undefined) throw new Unresolvable(ref);
      const contents = anchor.dynamic
        ? this.resolveDynamicAnchor(unquote(fragment), anchor.contents)
        : anchor.contents;
      return {
        contents,
        resolver: new Resolver(this.registry, base, this),
      };
    }

    return {
      contents: resource.contents,
      resolver: new Resolver(this.registry, base, this),
    };
  }

  /**
   * `$dynamicRef` semantics: the outermost `$dynamicAnchor` of the same name
   * anywhere in the dynamic scope wins over the lexically nearest one.
   */
  resolveDynamicAnchor(name, fallback) {
    let found = fallback;
    const scope = [...this.dynamicScope()];
    for (let i = scope.length - 1; i >= 0; i -= 1) {
      const candidate = this.registry.anchors.get(anchorKey(scope[i], name));
      if (candidate && candidate.dynamic) return candidate.contents;
    }
    return found;
  }

  /** `$recursiveRef: "#"` — the outermost `$recursiveAnchor: true` in scope. */
  lookupRecursiveRef() {
    const resolved = this.lookup('#');
    if (!isObject(resolved.contents) || getKey(resolved.contents, '$recursiveAnchor') !== true) {
      return resolved;
    }
    const scope = [...this.dynamicScope()];
    for (let i = scope.length - 1; i >= 0; i -= 1) {
      const resource = this.lookupResource(scope[i]);
      if (
        resource &&
        isObject(resource.contents) &&
        getKey(resource.contents, '$recursiveAnchor') === true
      ) {
        return {
          contents: resource.contents,
          resolver: new Resolver(this.registry, scope[i], this),
        };
      }
    }
    return resolved;
  }
}

/** Build the resolver used for a top-level schema document. */
export function resolverWithRoot(registry, contents, spec) {
  const id = spec.idOf(contents);
  const uri = id === null ? '' : urlDefrag(urlJoin('', id))[0];
  registry.addResource(uri, contents, spec);
  registry.crawl(contents, uri, spec);
  return new Resolver(registry, uri, null);
}

