    this.registry = registry;
    this.baseUri = baseUri;
    this.previous = previous;
  }

  /** Base URIs currently on the dynamic scope stack, innermost first. */
  *dynamicScope() {
    let resolver = this;
    while (resolver !== null) {
      yield resolver.baseUri;
      resolver = resolver.previous;
    }
  }

  /** Enter a subschema, adopting its `$id` as the new base if it has one. */
  inSubresource(contents, spec) {
    const id = spec.idOf(contents);
    if (id === null) return this;
    return new Resolver(this.registry, urlJoin(this.baseUri, id), this.previous);
  }

  lookupResource(uri) {
    const found = this.registry.resources.get(uri);
    if (found) return found;
    const withHash = this.registry.resources.get(`${uri}#`);
    if (withHash) return withHash;
    return null;
  }

  /**
   * Resolve `ref` relative to the current base, returning the referenced
   * schema plus a resolver scoped to it.
   */
  lookup(ref) {
    let uri;
    let fragment;
    if (ref.startsWith('#')) {
      uri = urlDefrag(this.baseUri)[0];
      fragment = ref.slice(1);
    } else {
      [uri, fragment] = urlDefrag(urlJoin(this.baseUri, ref));
    }

    const resource = this.lookupResource(uri);
    if (resource === null) throw new Unresolvable(ref);

    const { spec } = resource;
    let base = uri;

    if (fragment.startsWith('/')) {
      // Track `$id` declarations passed on the way down: they move the base.
      const contents = resolvePointer(resource.contents, unquote(fragment), (step) => {
        const id = spec.idOf(step);
        if (id !== null) base = urlDefrag(urlJoin(base, id))[0];
      });
      return {
        contents,
        resolver: new Resolver(this.registry, base, this),
      };
    }

    if (fragment) {
      const anchor = this.registry.anchors.get(anchorKey(uri, unquote(fragment)));
      if (anchor === undefined) throw new Unresolvable(ref);
      const contents = anchor.dynamic
        ? this.resolveDynamicAnchor(unquote(fragment), anchor.contents)
        : anchor.contents;
      return {
        contents,
        resolver: new Resolver(this.registry, base, this),
      };
    }

    return {
      contents: resource.contents,
      resolver: new Resolver(this.registry, base, this),
    };
  }

  /**
   * `$dynamicRef` semantics: the outermost `$dynamicAnchor` of the same name
   * anywhere in the dynamic scope wins over the lexically nearest one.
   */
  resolveDynamicAnchor(name, fallback) {
    let found = fallback;
    const scope = [...this.dynamicScope()];
    for (let i = scope.length - 1; i >= 0; i -= 1) {
      const candidate = this.registry.anchors.get(anchorKey(scope[i], name));
      if (candidate && candidate.dynamic) return candidate.contents;
    }
    return found;
  }

  /** `$recursiveRef: "#"` — the outermost `$recursiveAnchor: true` in scope. */
  lookupRecursiveRef() {
    const resolved = this.lookup('#');
    if (!isObject(resolved.contents) || getKey(resolved.contents, '$recursiveAnchor') !== true) {
      return resolved;
    }
    const scope = [...this.dynamicScope()];
    for (let i = scope.length - 1; i >= 0; i -= 1) {
      const resource = this.lookupResource(scope[i]);
      if (
        resource &&
        isObject(resource.contents) &&
        getKey(resource.contents, '$recursiveAnchor') === true
      ) {
        return {
          contents: resource.contents,
          resolver: new Resolver(this.registry, scope[i], this),
        };
      }
    }
    return resolved;
  }
}

/** Build the resolver used for a top-level schema document. */
export function resolverWithRoot(registry, contents, spec) {
  const id = spec.idOf(contents);
  const uri = id === null ? '' : urlDefrag(urlJoin('', id))[0];
  registry.addResource(uri, contents, spec);
  registry.crawl(contents, uri, spec);
  return new Resolver(registry, uri, null);
}

