/** Small helpers shared by the keyword implementations. */

import { isArray, isObject, isString, keysOf, getKey, hasKey } from '../json/values.mjs';
import { PythonTypeError } from '../errors.mjs';

/** `for x in value` as CPython performs it. */
export function pyIterate(value) {
  if (isString(value)) return Array.from(value);
  if (isArray(value)) return value;
  if (isObject(value)) return keysOf(value);
  throw new PythonTypeError(`'${pyTypeName(value)}' object is not iterable`);
}

/** `len(value)` for the container kinds a schema can hold. */
export function pyLen(value) {
  if (isString(value)) return Array.from(value).length;
  if (isArray(value)) return value.length;
  if (isObject(value)) return keysOf(value).length;
  throw new PythonTypeError(`object of type '${pyTypeName(value)}' has no len()`);
}

/** `x in container` for the container kinds a schema can hold. */
export function pyContains(container, member) {
  if (isObject(container)) return hasKey(container, member);
  if (isArray(container)) return container.some((each) => each === member);
  if (isString(container)) return isString(member) && container.includes(member);
  throw new PythonTypeError(
    `argument of type '${pyTypeName(container)}' is not iterable`,
  );
}

export function pyTypeName(value) {
  if (value === null) return 'NoneType';
  if (value === true || value === false) return 'bool';
  if (typeof value === 'string') return 'str';
  if (typeof value === 'number' || typeof value === 'bigint') return 'int';
  if (isArray(value)) return 'list';
  if (isObject(value)) return 'dict';
  return 'float';
}

/** `jsonschema._utils.ensure_list` */
export function ensureList(thing) {
  if (isString(thing)) return [thing];
  return pyIterate(thing);
}

/** `jsonschema._utils.find_additional_properties` */
export function findAdditionalProperties(instance, schema, search) {
  const properties = getKey(schema, 'properties', {});
  const patternKeys = isObject(getKey(schema, 'patternProperties'))
    ? keysOf(schema.patternProperties)
    : [];
  const patterns = patternKeys.join('|');

  const extras = [];
  for (const property of keysOf(instance)) {
    let known;
    try {
      known = pyContains(properties, property);
    } catch {
      known = false;
    }
    if (known) continue;
    if (patterns && search(patterns, property)) continue;
    extras.push(property);
  }
  return extras;
}

export function itemsAndSubschemas(instance, schemas) {
  // Python's `zip` stops at the shorter of the two sequences.
  const count = Math.min(instance.length, schemas.length);
  const pairs = [];
  for (let i = 0; i < count; i += 1) pairs.push([i, instance[i], schemas[i]]);
  return pairs;
}

