/**
 * Keyword implementations shared across drafts, following `jsonschema._keywords`.
 *
 * Each keyword is a generator yielding `ValidationError`s.  How many errors a
 * keyword yields is as much a part of its contract as whether it yields any:
 * applicators such as `properties` pass through every error from the subschema,
 * while `anyOf`, `oneOf` and `not` always collapse to a single error whose
 * `context` carries the detail.
 */

import { ValidationError, PythonTypeError } from '../errors.mjs';
import { equal, uniq } from '../json/equality.mjs';
import {
  isPyNumber,
  numberOf,
  pyMod,
  pyIntOfFloat,
  PyFloat,
  ZeroDivisionError,
  OverflowError,
  compareNumbers,
} from '../json/numbers.mjs';
import {
  isArray,
  isObject,
  isString,
  isBool,
  keysOf,
  getKey,
  hasKey,
  codePointLength,
} from '../json/values.mjs';
import { search } from '../regex/python-regex.mjs';
import {
  ensureList,
  findAdditionalProperties,
  itemsAndSubschemas,
  pyIterate,
  pyLen,
  pyContains,
  pyTypeName,
} from './utils.mjs';

const error = (message, extra) => new ValidationError(message, extra);

function requireNumber(value, operator) {
  if (!isPyNumber(value)) {
    throw new PythonTypeError(
      `'${operator}' not supported between instances of 'int' and '${pyTypeName(value)}'`,
    );
  }
}

export function* type(validator, types, instance, schema) {
  const list = ensureList(types);
  for (const each of list) {
    if (validator.isType(instance, each)) return;
  }
  yield error(`${repr(instance)} is not of type ${list.map(repr).join(', ')}`);
}

export function* enum_(validator, enums, instance, schema) {
  for (const each of pyIterate(enums)) {
    if (equal(each, instance)) return;
  }
  yield error(`${repr(instance)} is not one of ${repr(enums)}`);
}

export function* const_(validator, constValue, instance, schema) {
  if (!equal(constValue, instance)) {
    yield error(`${repr(constValue)} was expected`);
  }
}

export function* minimum(validator, bound, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  requireNumber(bound, '<');
  if (compareNumbers(instance, bound) < 0) {
    yield error(`${repr(instance)} is less than the minimum of ${repr(bound)}`);
  }
}

export function* maximum(validator, bound, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  requireNumber(bound, '>');
  if (compareNumbers(instance, bound) > 0) {
    yield error(`${repr(instance)} is greater than the maximum of ${repr(bound)}`);
  }
}

export function* exclusiveMinimum(validator, bound, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  requireNumber(bound, '<=');
  if (compareNumbers(instance, bound) <= 0) {
    yield error(
      `${repr(instance)} is less than or equal to the minimum of ${repr(bound)}`,
    );
  }
}

export function* exclusiveMaximum(validator, bound, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  requireNumber(bound, '>=');
  if (compareNumbers(instance, bound) >= 0) {
    yield error(
      `${repr(instance)} is greater than or equal to the maximum of ${repr(bound)}`,
    );
  }
}

export function* multipleOf(validator, divisor, instance, schema) {
  if (!validator.isType(instance, 'number')) return;

  let failed;
  if (divisor instanceof PyFloat) {
    // Python divides and checks the quotient is integral; the float rounding
    // this introduces is observable, so it is reproduced rather than avoided.
    const d = numberOf(divisor);
    if (d === 0) throw new ZeroDivisionError('float division by zero');
    const quotient = numberOf(instance) / d;
    if (Number.isNaN(quotient)) {
      throw new PythonTypeError('cannot convert float NaN to integer', 'ValueError');
    }
    try {
      failed = pyIntOfFloat(quotient) !== quotient;
    } catch (err) {
      if (err instanceof OverflowError) failed = true;
      else throw err;
    }
  } else {
    if (!isPyNumber(divisor) && !isBool(divisor)) {
      throw new PythonTypeError(
        `unsupported operand type(s) for %: 'int' and '${pyTypeName(divisor)}'`,
      );
    }
    const d = isBool(divisor) ? (divisor ? 1 : 0) : divisor;
    failed = pyMod(instance, d) !== 0 && pyMod(instance, d) !== 0n;
  }

  if (failed) {
    yield error(`${repr(instance)} is not a multiple of ${repr(divisor)}`);
  }
}

export function* minItems(validator, bound, instance, schema) {
  if (validator.isType(instance, 'array') && instance.length < numberOf(bound)) {
    yield error(`${repr(instance)} should be non-empty`);
  }
}

export function* maxItems(validator, bound, instance, schema) {
  if (validator.isType(instance, 'array') && instance.length > numberOf(bound)) {
    yield error(`${repr(instance)} is too long`);
  }
}

export function* uniqueItems(validator, unique, instance, schema) {
  if (unique && validator.isType(instance, 'array') && !uniq(instance)) {
    yield error(`${repr(instance)} has non-unique elements`);
  }
}

export function* minLength(validator, bound, instance, schema) {
  if (validator.isType(instance, 'string') && codePointLength(instance) < numberOf(bound)) {
    yield error(`${repr(instance)} is too short`);
  }
}

export function* maxLength(validator, bound, instance, schema) {
  if (validator.isType(instance, 'string') && codePointLength(instance) > numberOf(bound)) {
    yield error(`${repr(instance)} is too long`);
  }
}

export function* pattern(validator, patrn, instance, schema) {
  if (validator.isType(instance, 'string') && !search(patrn, instance)) {
    yield error(`${repr(instance)} does not match ${repr(patrn)}`);
  }
}

export function* format(validator, formatName, instance, schema) {
  // A `format_checker` is only attached when the caller asks for one; the
  // original script does not, so `format` is a pure annotation here.
  if (validator.formatChecker === null || validator.formatChecker === undefined) return;
  const failure = validator.formatChecker.check(instance, formatName);
  if (failure) yield error(failure);
}

export function* minProperties(validator, bound, instance, schema) {
  if (validator.isType(instance, 'object') && keysOf(instance).length < numberOf(bound)) {
    yield error(`${repr(instance)} does not have enough properties`);
  }
}

export function* maxProperties(validator, bound, instance, schema) {
  if (validator.isType(instance, 'object') && keysOf(instance).length > numberOf(bound)) {
    yield error(`${repr(instance)} has too many properties`);
  }
}

export function* required(validator, requiredProperties, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of pyIterate(requiredProperties)) {
    if (!hasKey(instance, property)) {
      yield error(`${repr(property)} is a required property`);
    }
  }
}

export function* properties(validator, props, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of keysOf(props)) {
    if (hasKey(instance, property)) {
      yield* validator.descend(instance[property], props[property], property, property);
    }
  }
}

export function* patternProperties(validator, patterns, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const patrn of keysOf(patterns)) {
    const subschema = patterns[patrn];
    for (const key of keysOf(instance)) {
      if (search(patrn, key)) {
        yield* validator.descend(instance[key], subschema, key, patrn);
      }
    }
  }
}

export function* additionalProperties(validator, additional, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  const extras = findAdditionalProperties(instance, schema, search);

  if (validator.isType(additional, 'object')) {
    for (const extra of extras) {
      yield* validator.descend(instance[extra], additional, extra);
    }
  } else if (!additional && extras.length) {
    // A single error names every unexpected property, rather than one each.
    yield error(
      `Additional properties are not allowed (${extrasMessage(extras)})`,
    );
  }
}

export function* propertyNames(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of keysOf(instance)) {
    yield* validator.descend(property, subschema);
  }
}

export function* allOf(validator, subschemas, instance, schema) {
  let index = 0;
  for (const subschema of pyIterate(subschemas)) {
    yield* validator.descend(instance, subschema, null, index);
    index += 1;
  }
}

export function* anyOf(validator, subschemas, instance, schema) {
  const all = [];
  let index = 0;
  for (const subschema of pyIterate(subschemas)) {
    const errors = [...validator.descend(instance, subschema, null, index)];
    if (errors.length === 0) return;
    all.push(...errors);
    index += 1;
  }
  yield error(`${repr(instance)} is not valid under any of the given schemas`, {
    context: all,
  });
}

export function* oneOf(validator, subschemas, instance, schema) {
  const list = pyIterate(subschemas);
  const all = [];
  let matchedIndex = -1;

  for (let index = 0; index < list.length; index += 1) {
    const errors = [...validator.descend(instance, list[index], null, index)];
    if (errors.length === 0) {
      matchedIndex = index;
      break;
    }
    all.push(...errors);
  }

  if (matchedIndex === -1) {
    yield error(`${repr(instance)} is not valid under any of the given schemas`, {
      context: all,
    });
    return;
  }

  // Python resumes the *same* iterator, so only the subschemas after the first
  // match are re-checked for the "valid under each of" complaint.
  const more = [];
  for (let index = matchedIndex + 1; index < list.length; index += 1) {
    if (validator.evolve(list[index]).isValid(instance)) more.push(index);
  }
  if (more.length) {
    yield error(`${repr(instance)} is valid under each of ${more.join(', ')}`);
  }
}

export function* not_(validator, subschema, instance, schema) {
  if (validator.evolve(subschema).isValid(instance)) {
    yield error(`${repr(instance)} should not be valid under ${repr(subschema)}`);
  }
}

export function* if_(validator, ifSchema, instance, schema) {
  if (validator.evolve(ifSchema).isValid(instance)) {
    if (hasKey(schema, 'then')) {
      yield* validator.descend(instance, schema.then, null, 'then');
    }
  } else if (hasKey(schema, 'else')) {
    yield* validator.descend(instance, schema.else, null, 'else');
  }
}

export function* ref(validator, reference, instance, schema) {
  yield* validator.validateReference(reference, instance);
}

/** Draft 6 / Draft 7 `contains`: any single match satisfies it. */
export function* containsLegacy(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  for (const element of instance) {
    if (validator.evolve(subschema).isValid(element)) return;
  }
  yield error(`${repr(instance)} does not contain items matching the given schema`);
}

export function repr(value) {
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'string') return JSON.stringify(value);
  if (isArray(value)) return `[${value.map(repr).join(', ')}]`;
  if (isObject(value)) {
    return `{${keysOf(value)
      .map((key) => `${repr(key)}: ${repr(value[key])}`)
      .join(', ')}}`;
  }
  return String(numberOf(value));
}

export function extrasMessage(extras) {
  const verb = extras.length === 1 ? 'was' : 'were';
  return `${extras.map(repr).join(', ')} ${verb} unexpected`;
}

