/**
 * Keywords whose behaviour is specific to Draft 3 and Draft 4, following
 * `jsonschema._legacy_keywords`.
 *
 * Draft 3 in particular is a different language: `required` is a boolean flag
 * on each property rather than a list, `type` may contain inline subschemas,
 * and `extends`/`disallow`/`divisibleBy` have no modern equivalents.  Draft 3
 * and Draft 4 also spell exclusive bounds as boolean modifiers on
 * `minimum`/`maximum` instead of as separate numeric keywords.
 */

import { ValidationError } from '../errors.mjs';
import { compareNumbers } from '../json/numbers.mjs';
import { isObject, isString, keysOf, getKey, hasKey } from '../json/values.mjs';
import { repr, extrasMessage } from './common.mjs';
import { ensureList, pyIterate, itemsAndSubschemas } from './utils.mjs';

const error = (message, extra) => new ValidationError(message, extra);

/** Draft 3's `type`, which may list inline subschemas alongside type names. */
export function* typeDraft3(validator, types, instance, schema) {
  const list = ensureList(types);
  const allErrors = [];

  for (let index = 0; index < list.length; index += 1) {
    const each = list[index];
    if (each === 'any') return;
    if (validator.isType(each, 'object')) {
      const errors = [...validator.descend(instance, each, null, index)];
      if (errors.length === 0) return;
      allErrors.push(...errors);
    } else if (validator.isType(instance, each)) {
      return;
    }
  }

  yield error(`${repr(instance)} is not of type ${list.map(repr).join(', ')}`, {
    context: allErrors,
  });
}

export function* disallowDraft3(validator, disallow, instance, schema) {
  for (const disallowed of ensureList(disallow)) {
    if (validator.evolve({ type: [disallowed] }).isValid(instance)) {
      yield error(`${repr(disallowed)} is disallowed for ${repr(instance)}`);
    }
  }
}

export function* extendsDraft3(validator, extendsValue, instance, schema) {
  if (validator.isType(extendsValue, 'object')) {
    yield* validator.descend(instance, extendsValue);
    return;
  }
  let index = 0;
  for (const subschema of pyIterate(extendsValue)) {
    yield* validator.descend(instance, subschema, null, index);
    index += 1;
  }
}

/** Draft 3 folds `required` into each entry of `properties`. */
export function* propertiesDraft3(validator, props, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of keysOf(props)) {
    const subschema = props[property];
    if (hasKey(instance, property)) {
      yield* validator.descend(instance[property], subschema, property, property);
    } else if (getKey(subschema, 'required', false)) {
      yield error(`${repr(property)} is a required property`);
    }
  }
