export function* dependenciesDraft3(validator, dependencies, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of keysOf(dependencies)) {
    if (!hasKey(instance, property)) continue;
    const dependency = dependencies[property];
    if (validator.isType(dependency, 'object')) {
      yield* validator.descend(instance, dependency, null, property);
    } else if (validator.isType(dependency, 'string')) {
      if (!hasKey(instance, dependency)) {
        yield error(`${repr(dependency)} is a dependency of ${repr(property)}`);
      }
