/** Draft 4 through Draft 7: a dependency is either a schema or a name list. */
export function* dependenciesDraft4To7(validator, dependencies, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of keysOf(dependencies)) {
    if (!hasKey(instance, property)) continue;
    const dependency = dependencies[property];
    if (validator.isType(dependency, 'array')) {
