export function* maximumDraft3Draft4(validator, bound, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  const exclusive = getKey(schema, 'exclusiveMaximum', false);
  const comparison = compareNumbers(instance, bound);
  const failed = exclusive ? comparison >= 0 : comparison > 0;
  if (failed) {
    const how = exclusive ? 'greater than or equal to' : 'greater than';
    yield error(`${repr(instance)} is ${how} the maximum of ${repr(bound)}`);
  }
