  if (!validator.isType(instance, 'array')) return;
  if (validator.isType(items, 'array')) {
    for (const [index, item, subschema] of itemsAndSubschemas(instance, items)) {
      yield* validator.descend(item, subschema, index, index);
    }
    return;
  }
  for (let index = 0; index < instance.length; index += 1) {
    yield* validator.descend(instance[index], items, index);
  }
