/**
 * Keywords introduced by Draft 2019-09 and Draft 2020-12.
 *
 * `contains` grows `minContains`/`maxContains`, `dependencies` splits into
 * `dependentRequired` and `dependentSchemas`, tuple validation moves from
 * `items` to `prefixItems`, and the `unevaluated*` pair arrives together with
 * the dynamic reference keywords.
 */

import { ValidationError } from '../errors.mjs';
import { numberOf } from '../json/numbers.mjs';
import { keysOf, getKey, hasKey } from '../json/values.mjs';
import { repr, extrasMessage } from './common.mjs';
import { pyIterate, pyLen, itemsAndSubschemas } from './utils.mjs';
import {
  findEvaluatedItemIndexes,
  findEvaluatedItemIndexes2019,
  findEvaluatedPropertyKeys,
} from './annotations.mjs';

const error = (message, extra) => new ValidationError(message, extra);

export function* contains(validator, subschema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;

  const minContains = numberOf(getKey(schema, 'minContains', 1));
  const maxContains = numberOf(getKey(schema, 'maxContains', instance.length));

  let matches = 0;
  for (const element of instance) {
    if (validator.evolve(subschema).isValid(element)) {
      matches += 1;
      if (matches > maxContains) {
        yield error('too many matches');
        return;
      }
    }
  }

  if (matches < minContains) {
    if (matches === 0) {
      yield error(`${repr(instance)} does not contain items matching the given schema`);
    } else {
      yield error('too few matches');
    }
  }
}

export function* dependentRequired(validator, dependencies, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of keysOf(dependencies)) {
    if (!hasKey(instance, property)) continue;
    for (const each of pyIterate(dependencies[property])) {
      if (!hasKey(instance, each)) {
        yield error(`${repr(each)} is a dependency of ${repr(property)}`);
      }
    }
  }
}

export function* dependentSchemas(validator, dependencies, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of keysOf(dependencies)) {
    if (!hasKey(instance, property)) continue;
    yield* validator.descend(instance, dependencies[property], null, property);
  }
}

export function* prefixItems(validator, prefix, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  for (const [index, item, subschema] of itemsAndSubschemas(instance, prefix)) {
    yield* validator.descend(item, subschema, index, index);
  }
}

/** Draft 2020-12 `items` only sees what `prefixItems` did not cover. */
export function* items(validator, itemsSchema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const prefix = hasKey(schema, 'prefixItems') ? pyLen(schema.prefixItems) : 0;
  for (let index = prefix; index < instance.length; index += 1) {
    yield* validator.descend(instance[index], itemsSchema, index);
  }
}

