  if (!validator.isType(instance, 'array')) return;
  const evaluated = new Set(finder(validator, instance, schema));
  const leftover = [];
  for (let index = 0; index < instance.length; index += 1) {
    if (!evaluated.has(index)) leftover.push(instance[index]);
  }
  if (leftover.length) {
    yield error(`Unevaluated items are not allowed (${extrasMessage(leftover)})`);
  }
