  const resolved = validator.resolver.lookupRecursiveRef();
  yield* validator.descendWithResolver(instance, resolved.contents, resolved.resolver);
}

export function* dynamicRef(validator, reference, instance, schema) {
  yield* validator.validateReference(reference, instance);
}

function firstError(iterable) {
  for (const each of iterable) return each;
  return null;
}

