#!/usr/bin/env node
/**
 * Node.js port of `test13.py`.
 *
 * Reads a JSON instance and a JSON schema from `--a` and `--b`, selects the
 * validator dialect the way `jsonschema.validators.validator_for` does, and
 * prints the validator class name, the validity verdict and the number of
 * top-level validation errors — one per line, exactly as the original.
 */

import { basename } from 'node:path';

import { ArgumentParser, ArgumentError } from './lib/cli/argparse.mjs';
import { loads } from './lib/json/parse.mjs';
import { validatorFor, createValidator } from './lib/validator.mjs';

function main(argv) {
  const parser = new ArgumentParser({ prog: basename(process.argv[1] || 'test13.mjs') });
  parser.addArgument('--a', { dest: 'a', required: true, help: 'instance (JSON string)' });
  parser.addArgument('--b', { dest: 'b', required: true, help: 'schema (JSON string)' });
  const args = parser.parseArgs(argv);

  const instance = loads(args.a);
  const schema = loads(args.b);

  // Use validator_for to get appropriate validator class
  const validatorClass = validatorFor(schema); // Get validator class for schema
  const validator = createValidator(validatorClass, schema); // Create instance

  const result = validator.isValid(instance); // Validate
  const errors = [...validator.iterErrors(instance)]; // Get errors

  process.stdout.write(`${validatorClass.className}\n`);
  process.stdout.write(`${result ? 'True' : 'False'}\n`);
  process.stdout.write(`${errors.length}\n`);
}

try {
  main(process.argv.slice(2));
} catch (err) {
  if (err instanceof ArgumentError) {
    process.stderr.write(err.usage);
    process.stderr.write(err.message);
    process.exit(2);
  }
  const label = err && err.pythonType ? err.pythonType : 'Exception';
  process.stderr.write('Traceback (most recent call last):\n');
  process.stderr.write(`  File "test13.mjs", line 1, in <module>\n`);
  process.stderr.write(`${label}: ${err && err.message ? err.message : String(err)}\n`);
  process.exit(1);
}

