// Differential harness: replays recorded probe vectors through the JS port
// in-process and compares the three printed lines with the Python output.
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

import { loads } from '/output/lib/json/parse.mjs';
import { validatorFor, createValidator } from '/output/lib/validator.mjs';

const PROBE_DIR = '/workspace/probes';

function runOne(aText, bText) {
  const instance = loads(aText);
  const schema = loads(bText);
  const cls = validatorFor(schema);
  const validator = createValidator(cls, schema);
  const result = validator.isValid(instance);
  const errors = [...validator.iterErrors(instance)];
  return `${cls.className}\n${result ? 'True' : 'False'}\n${errors.length}\n`;
}

const only = process.argv[2];
const files = readdirSync(PROBE_DIR)
  .filter((f) => f.endsWith('.jsonl'))
  .filter((f) => !only || f.includes(only));

let total = 0;
let pass = 0;
const buckets = new Map();

for (const file of files) {
  const lines = readFileSync(join(PROBE_DIR, file), 'utf8').split('\n').filter(Boolean);
  for (const line of lines) {
    let vector;
    try {
      vector = JSON.parse(line);
    } catch {
      continue;
    }
    if (typeof vector.a !== 'string' || typeof vector.b !== 'string') continue;
    total += 1;

    let actual;
    let threw = null;
    try {
      actual = runOne(vector.a, vector.b);
    } catch (err) {
      threw = err;
      actual = null;
    }

    const pythonCrashed = vector.exit !== 0 || !/^Draft\d/.test(vector.out || '');

    if (pythonCrashed) {
      // Python raised; the port matches if it also refuses to produce output.
      if (threw) pass += 1;
      else record(buckets, file, vector, `expected crash, got ${JSON.stringify(actual)}`);
      continue;
    }

    if (threw) {
      record(buckets, file, vector, `threw ${threw.name}: ${threw.message}`);
      continue;
    }
    if (actual === vector.out) pass += 1;
    else record(buckets, file, vector, `got ${JSON.stringify(actual)} want ${JSON.stringify(vector.out)}`);
  }
}

function record(map, file, vector, detail) {
  if (!map.has(file)) map.set(file, []);
  map.get(file).push({ a: vector.a, b: vector.b, detail });
}

console.log(`total=${total} pass=${pass} fail=${total - pass}`);
const limit = Number(process.env.SHOW || 12);
for (const [file, fails] of [...buckets].sort((x, y) => y[1].length - x[1].length)) {
  console.log(`\n### ${file}: ${fails.length} failures`);
  for (const f of fails.slice(0, limit)) {
    console.log(`  a=${trunc(f.a)}\n  b=${trunc(f.b)}\n  ${f.detail}`);
  }
}

function trunc(text) {
  return text.length > 200 ? `${text.slice(0, 200)}…` : text;
}

