function bigOf(value) {
  if (typeof value === 'bigint') return value;
  if (typeof value === 'number' && Number.isInteger(value)) return BigInt(value);
  const n = numberOf(value);
  if (Number.isInteger(n)) return BigInt(n);
  return null;
}

/**
 * Three-way comparison with Python's cross-type numeric semantics.
 * Returns -1, 0, 1, or NaN when either operand is NaN.
 */
export function compareNumbers(a, b) {
  if (typeof a === 'bigint' || typeof b === 'bigint') {
    const x = bigOf(a);
    const y = bigOf(b);
    if (x !== null && y !== null) return x < y ? -1 : x > y ? 1 : 0;
  }
  const x = numberOf(a);
  const y = numberOf(b);
  if (Number.isNaN(x) || Number.isNaN(y)) return NaN;
  return x < y ? -1 : x > y ? 1 : 0;
}

export function numbersEqual(a, b) {
  return compareNumbers(a, b) === 0;
}

/**
 * Python's `%` for the operands jsonschema feeds `multipleOf`.
 * Result carries the sign of the divisor, unlike JavaScript's remainder.
 */
export function pyMod(a, b) {
  if (typeof a === 'bigint' && typeof b === 'bigint') {
    if (b === 0n) throw new ZeroDivisionError('integer modulo by zero');
    const r = a % b;
    return r !== 0n && (r < 0n) !== (b < 0n) ? r + b : r;
  }
  const x = numberOf(a);
  const y = numberOf(b);
  if (y === 0) throw new ZeroDivisionError('integer modulo by zero');
  const r = x % y;
  return r !== 0 && r < 0 !== y < 0 ? r + y : r;
}

