/**
 * Python-faithful numeric tower for JSON values.
 *
 * Python's `json` module produces two distinct numeric types:
 *   - `int`   for literals without a fraction or exponent part (`1`, `-7`)
 *   - `float` for literals with either (`1.0`, `1e2`, `-0.5`)
 *
 * `jsonschema` observes that distinction (e.g. Draft 3/4 report `1.0` as *not*
 * an integer, and `multipleOf` picks a different algorithm for float divisors),
 * so JavaScript's single `number` type is not enough.  Floats are therefore
 * boxed in `PyFloat`; unboxed `number`/`bigint` values mean Python `int`.
 */

/** A value that came from a JSON literal carrying a fraction or exponent. */
export class PyFloat {
  constructor(value) {
    this.value = value;
  }

  valueOf() {
    return this.value;
  }

  toString() {
    return String(this.value);
  }
}

export function pyFloat(value) {
  return new PyFloat(value);
}

export function isPyFloat(value) {
  return value instanceof PyFloat;
}

/** True for Python `int` values (booleans are deliberately excluded). */
export function isPyInt(value) {
  return typeof value === 'number' || typeof value === 'bigint';
}

/** True for Python `int` or `float`; booleans are not numbers to jsonschema. */
export function isPyNumber(value) {
  return typeof value === 'number' || typeof value === 'bigint' || value instanceof PyFloat;
}

/** Unbox to a plain JavaScript number (lossy for huge ints, as Python's float() is). */
export function numberOf(value) {
  if (value instanceof PyFloat) return value.value;
  if (typeof value === 'bigint') return Number(value);
  return value;
}

/** Whether the numeric value is mathematically an integer (1.0 counts). */
export function isIntegral(value) {
  if (typeof value === 'bigint') return true;
  const n = numberOf(value);
  return Number.isFinite(n) && Math.floor(n) === n;
}

function bigOf(value) {
  if (typeof value === 'bigint') return value;
  if (typeof value === 'number' && Number.isInteger(value)) return BigInt(value);
  const n = numberOf(value);
  if (Number.isInteger(n)) return BigInt(n);
  return null;
}

/**
 * Three-way comparison with Python's cross-type numeric semantics.
 * Returns -1, 0, 1, or NaN when either operand is NaN.
 */
export function compareNumbers(a, b) {
  if (typeof a === 'bigint' || typeof b === 'bigint') {
    const x = bigOf(a);
    const y = bigOf(b);
    if (x !== null && y !== null) return x < y ? -1 : x > y ? 1 : 0;
  }
  const x = numberOf(a);
  const y = numberOf(b);
  if (Number.isNaN(x) || Number.isNaN(y)) return NaN;
  return x < y ? -1 : x > y ? 1 : 0;
}

export function numbersEqual(a, b) {
  return compareNumbers(a, b) === 0;
}

/**
 * Python's `%` for the operands jsonschema feeds `multipleOf`.
 * Result carries the sign of the divisor, unlike JavaScript's remainder.
 */
export function pyMod(a, b) {
  if (typeof a === 'bigint' && typeof b === 'bigint') {
