function gcd(a, b) {
  let x = a < 0n ? -a : a;
  let y = b < 0n ? -b : b;
  while (y) {
    const t = x % y;
    x = y;
    y = t;
  }
  return x;
}

/**
 * The exact rational value of a number, as `fractions.Fraction` computes it.
 * Doubles are dyadic rationals, so this is lossless.
 */
export function exactFraction(value) {
  if (typeof value === 'bigint') return { num: value, den: 1n };
  if (value === true) return { num: 1n, den: 1n };
  if (value === false) return { num: 0n, den: 1n };

  const x = numberOf(value);
  if (Number.isNaN(x)) throw new ValueError('cannot convert NaN to integer ratio');
  if (!Number.isFinite(x)) {
    throw new OverflowError('cannot convert Infinity to integer ratio');
  }
  if (Number.isInteger(x) && Math.abs(x) <= Number.MAX_SAFE_INTEGER) {
    return { num: BigInt(x), den: 1n };
  }

  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, x);
  const hi = view.getUint32(0);
  const lo = view.getUint32(4);
  const negative = (hi >>> 31) === 1;
  const biasedExponent = (hi >>> 20) & 0x7ff;
  let mantissa = (BigInt(hi & 0xfffff) << 32n) | BigInt(lo);

  let exponent;
  if (biasedExponent === 0) {
    exponent = -1074; // subnormal
  } else {
    mantissa |= 1n << 52n;
    exponent = biasedExponent - 1075;
  }

  let num = negative ? -mantissa : mantissa;
  let den = 1n;
  if (exponent >= 0) num <<= BigInt(exponent);
  else den = 1n << BigInt(-exponent);

  const divisor = gcd(num, den) || 1n;
  return { num: num / divisor, den: den / divisor };
