export function isExactMultiple(instance, divisor) {
  const a = exactFraction(instance);
  const b = exactFraction(divisor);
  if (b.num === 0n) throw new ZeroDivisionError('division by zero');
  const num = a.num * b.den;
  const den = a.den * b.num;
  const divisorGcd = gcd(num, den) || 1n;
  return den / divisorGcd === 1n || den / divisorGcd === -1n;
}

